/**
 * bug6047 真实数据浏览器联调验证（只读）
 *
 * 路径：登录 → /jgba/recordPriceMngSuzhou（价格备案申请）→ 点「项目名称」→ 项目选择弹窗 → 读「项目所在地」列
 * 只做打开弹窗 + 读取表格文本 + 截图，不保存不提交。
 *
 * 运行： $env:E2E_BASE_URL="http://127.0.0.1:8098"; node e2e/scripts/verify-bug6047-real.mjs
 */
import fs from 'fs'
import path from 'path'
import { chromium } from '@playwright/test'
import { loadE2eEnv, getLoginUsername, getLoginPassword, getLoginType } from '../fixtures/env-loader.js'
import { loginWithRealAccount, waitForRoutesReady, ensureDynamicRoutesRegistered } from '../fixtures/auth-helpers.js'

loadE2eEnv()

const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8098'
const OUT_DIR = path.resolve('e2e/output/bug6047')
fs.mkdirSync(OUT_DIR, { recursive: true })

/** 价格备案申请 列表路由（浏览器实测） */
const LIST_PATH = '/jgba/recordPriceMngSuzhou'

const log = (...a) => console.log('[bug6047]', ...a)

async function main() {
  const browser = await chromium.launch({ headless: process.env.HEADED === '1' ? false : true })
  const context = await browser.newContext({ viewport: { width: 1920, height: 911 }, baseURL: BASE_URL })
  const page = await context.newPage()

  /** 捕获 /building/project/page 的真实响应，用来核对 region 字段 */
  let projectApiSample = null
  page.on('response', async (r) => {
    if (r.url().includes('/building/project/page')) {
      try {
        const body = await r.json()
        const rows = body?.data?.rows || body?.data?.list || body?.rows || []
        projectApiSample = { status: r.status(), total: body?.data?.total, firstRowKeys: rows[0] ? Object.keys(rows[0]) : [], firstRow: rows[0] || null }
      } catch { /* ignore */ }
    }
  })

  try {
    log('baseURL =', BASE_URL)
    const vr = await page.request.get(`${BASE_URL}/version.json`).catch(() => null)
    if (vr && vr.ok()) log('站点版本 =', JSON.stringify(await vr.json()))

    await loginWithRealAccount(page, { loginType: getLoginType(), username: getLoginUsername(), password: getLoginPassword() })
    log('登录成功 →', page.url())
    await waitForRoutesReady(page).catch(() => {})
    await ensureDynamicRoutesRegistered(page)

    // 1) 打开价格备案申请列表
    await page.goto(`${BASE_URL}/#${LIST_PATH}`, { waitUntil: 'domcontentloaded' })
    await page.waitForTimeout(2500)
    await page.screenshot({ path: path.join(OUT_DIR, '01-list.png'), fullPage: true })
    log('列表页 URL =', page.url())

    // 2) 点「新增」进入申请页
    const addBtn = page.locator('button').filter({ hasText: /^\s*新\s*增\s*$/ }).first()
    if (await addBtn.count()) {
      await addBtn.click()
      log('已点击「新增」')
    } else {
      log('未找到「新增」按钮，候选按钮：', JSON.stringify((await page.locator('button').allInnerTexts()).slice(0, 20)))
    }
    await page.waitForTimeout(2500)
    await page.screenshot({ path: path.join(OUT_DIR, '02-detail.png'), fullPage: true })
    log('申请页 URL =', page.url())

    // 3) 点「项目名称」输入框打开弹窗
    const projInput = page.locator('input[placeholder="请选择项目名称"]').first()
    await projInput.waitFor({ state: 'visible', timeout: 20000 })
    log('点击「项目名称」选择框')
    await projInput.click()

    // 4) 等弹窗出现（标题：项目名称）
    const dialog = page.locator('.el-dialog__wrapper:visible').filter({ hasText: '项目名称' }).first()
    await dialog.waitFor({ state: 'visible', timeout: 20000 })
    await page.waitForTimeout(2500)
    await page.screenshot({ path: path.join(OUT_DIR, '03-dialog.png') })

    if (projectApiSample) {
      log('接口 /building/project/page status =', projectApiSample.status, 'total =', projectApiSample.total)
      log('首行字段名 =', JSON.stringify(projectApiSample.firstRowKeys))
      const r0 = projectApiSample.firstRow || {}
      log('首行 region =', JSON.stringify(r0.region), '| regionName =', JSON.stringify(r0.regionName))
    }

    // 5) 读「项目所在地」列
    const headers = await dialog.locator('thead th').allInnerTexts().catch(() => [])
    const colIdx = headers.findIndex((h) => h.includes('项目所在地'))
    log('表头 =', JSON.stringify(headers.map((h) => h.trim())), '\n项目所在地列索引 =', colIdx)

    const rows = dialog.locator('.el-table__body tbody tr')
    const rowCount = await rows.count()
    const cells = []
    for (let i = 0; i < Math.min(rowCount, 20); i++) {
      const tds = rows.nth(i).locator('td')
      if (colIdx >= 0 && colIdx < (await tds.count())) {
        cells.push({ row: i + 1, name: (await tds.nth(0).innerText()).trim(), region: (await tds.nth(colIdx).innerText()).trim() })
      }
    }
    const nonEmpty = cells.filter((c) => c.region)
    log('行数 =', rowCount, '| 项目所在地非空 =', nonEmpty.length)
    log('样例 =', JSON.stringify(cells.slice(0, 6), null, 1))

    const pass = colIdx >= 0 && nonEmpty.length > 0
    fs.writeFileSync(path.join(OUT_DIR, 'result.json'), JSON.stringify({
      baseUrl: BASE_URL, listPath: LIST_PATH, columnIndex: colIdx, rowCount,
      nonEmptyCount: nonEmpty.length, sample: cells.slice(0, 10),
      apiFirstRowKeys: projectApiSample?.firstRowKeys, pass
    }, null, 2))
    log('=== 结论 ===', pass ? 'PASS：项目所在地有值' : 'FAIL：项目所在地为空')

    // 6) 高亮截图
    if (colIdx >= 0) {
      await page.evaluate((idx) => {
        const dlg = [...document.querySelectorAll('.el-dialog__wrapper')].find(
          (d) => d.offsetParent !== null && d.innerText.includes('项目名称')
        )
        if (!dlg) return
        dlg.querySelectorAll('.el-table__body tbody tr').forEach((tr) => {
          const td = tr.children[idx]
          if (td) { td.style.background = '#fff3cd'; td.style.outline = '2px solid #ff9800'; td.style.fontWeight = '700' }
        })
        const th = dlg.querySelectorAll('thead th')[idx]
        if (th) { th.style.background = '#ffecb3' }
      }, colIdx)
      await page.waitForTimeout(500)
      await page.screenshot({ path: path.join(OUT_DIR, '04-dialog-highlight.png') })
      const box = await dialog.boundingBox()
      if (box) await page.screenshot({ path: path.join(OUT_DIR, '05-dialog-crop.png'), clip: box })
    }

    await browser.close()
    process.exitCode = pass ? 0 : 2
  } catch (err) {
    log('执行失败：', err?.stack || String(err))
    await page.screenshot({ path: path.join(OUT_DIR, '99-failure.png'), fullPage: true }).catch(() => {})
    await browser.close()
    process.exitCode = 1
  }
}

main()

